CaptureNoteDecisionViewOnNoteContentUpda:
event match {
  case NoteEventPO.Event.NoteContentUpdated(po) =>
    // 保守修补：仅更新可被正标识的既有行（主键 (noteId, "") 由 OnNoteCaptured 落地）；查无则静默跳过——宁可空跳不可错写
    val existing = scala.concurrent.Await.result(captureNoteDecisionViewRepository.findByIdentity(po.noteId, ""), scala.concurrent.duration.Duration("10s"))
    existing.foreach { row =>
      // S2-89 P0 根修＋P1 根治（2026-09-13）：description 列＝文件原文（MetarchRebuild/门消费·
      // OnNoteCaptured 分列契约「与 content 显示面分列」）——原实现只更 content 显示面，description
      // 列永不更新，land_service_sync「description 变→update-note-content」契约（B5b）落空→
      // truth_projection_gate 恒红（s77-draft-2026-09-13 首跑实证）。
      // P1 根治＝②层 UpdateNoteContent.description 参数（EP_S2_89 Phase 1 批）：po.description
      // 精确承载；空值保持原列（旧 journal 事件回放 upcast 得 ""——空值覆写会洗掉 OnNoteCaptured
      // 落的 description·S2-72 null 盲区同族教训）。
      val newDesc = if (po.description == null || po.description.isEmpty) row.description else po.description
      captureNoteDecisionViewRepository.upsert(row.copy(content = po.content, description = newDesc)) // 幂等路径：upsert ON DUPLICATE KEY UPDATE
    }
  case _ => () // 非本投影关注事件
}
// TODO(BUG-014/S2-11): 待 PO NoteContentUpdatedPO 补 questionId 或仓储提供按 noteId 全量反查后补精确行定位

