CatalogGraphViewOnMetadataAssembledHandl:
// MANUAL（S2-65 批E）：manifest 体不落图（体积不可控），只落 SHA-256 指纹与字节数供对账
// （退役手写件 DomainEventGraphMappings.manifestDigestProps L228-234 语义逐条对齐）
event match {
  case ModelCatalogEventPO.Event.MetadataAssembled(po) =>
    val bytes = if (po.manifest == null) Array.emptyByteArray
                else po.manifest.getBytes(java.nio.charset.StandardCharsets.UTF_8)
    val sha = java.security.MessageDigest.getInstance("SHA-256")
      .digest(bytes).map("%02x".format(_)).mkString
    catalogGraphViewRepository.updateNodeProps(po.catalogId, Map(
      "status" -> "ASSEMBLED", "version" -> po.version,
      "assembledAt" -> po.timestamp.toString, "tenantId" -> po.tenantId,
      "manifestSha256" -> sha, "manifestBytes" -> bytes.length.toString))
  case _ => () // 非本投影关注事件
}

