ConceptGraphViewOnConceptLandingsRecorde:
import net.imadz.metarch.infrastructure.graph.GraphMutationExecutor
// 图投影意图：把该概念的全部代码落点写进节点属性。
//
// 序列化形态：`updateNodeProps` 只收 `Map[String,String]` ⇒ anchors 压成一个字符串。
//   形态：`noteId|role|host|file|symbols(逗号分隔)` 多条以 `;;` 分隔——**可逆、可 grep**。
//   为什么不做 JSON：图属性是字符串面，JSON 里的引号/转义在 Neo4j 侧要二次转义，
//   而消费方（`by-note` 查询 / 图遍历）只需「这条知识落在哪」——竖线分隔足够了。
event match {
  case ConceptEventPO.Event.ConceptLandingsRecorded(po) =>
    val packed = po.anchors.map { a =>
      val syms = a.symbols.mkString(",")
      s"${a.noteId}|${a.role}|${a.host}|${a.file}|$syms"
    }.mkString(";;")
    // 挂账A（2026-09-29·租户图守卫知识腿）：guards 同 anchors 打包语义——
    //   `kind|ref|errCode|cond` 竖线连接（消费方只需「该命令受什么守卫约束」·
    //   不带 toStatus/notStatus 状态迁移细节，那些在写侧 FMD state）多条 ;; 分隔。
    //   guards 为空（旧 journal 事件回放/纯锚回写）时不写 guards 属性——保持节点干净。
    // ★ anchors 空同款分支（2026-09-29 字段批实证副作用）：anchors 空（guards/ruleRefs/
    //   fields 单腿推送的 update 增量）**不写 anchors/anchorsCount**——updateNodeProps
    //   `SET +=` 覆盖同键，空串写回＝抹掉既有锚（26 聚合 2311 锚被清零判例）。
    val props = scala.collection.mutable.LinkedHashMap[String, String]("tenantId" -> po.tenantId)
    if (po.anchors != null && po.anchors.nonEmpty) {
      props("anchors") = packed
      props("anchorsCount") = String.valueOf(po.anchors.size)
    }
    if (po.guards != null && po.guards.nonEmpty) {
      val packedGuards = po.guards.map(g => s"${g.kind}|${g.ref}|${g.errCode}|${g.cond}").mkString(";;")
      props("guards") = packedGuards
      props("guardsCount") = String.valueOf(po.guards.size)
    }
    // 4c（2026-09-29·租户图规则知识腿）：规则引用三槽直通——三槽各自打包+计数
    //   打包形态 `ruleId|errCode`（desc 中文长文不进图·写侧 FMD 已有）；槽位即分类
    //   （IR-TNT-INV-001 判例：ruleId 分段≠槽位）。三个计数属性与 S1 inv 三行同单位直判。
    //   三槽全空（旧 journal 事件回放/纯锚回写）不写属性——保持节点干净。
    if ((po.aggregateRuleRefs != null && po.aggregateRuleRefs.nonEmpty) ||
        (po.preconditionRefs != null && po.preconditionRefs.nonEmpty) ||
        (po.postconditionRefs != null && po.postconditionRefs.nonEmpty)) {
      if (po.aggregateRuleRefs != null && po.aggregateRuleRefs.nonEmpty) {
        props("aggregateRuleRefs") = po.aggregateRuleRefs.map(r => s"${r.ruleId}|${r.errCode}").mkString(";;")
        props("aggRefsCount") = String.valueOf(po.aggregateRuleRefs.size)
      }
      if (po.preconditionRefs != null && po.preconditionRefs.nonEmpty) {
        props("preconditionRefs") = po.preconditionRefs.map(r => s"${r.ruleId}|${r.errCode}").mkString(";;")
        props("preRefsCount") = String.valueOf(po.preconditionRefs.size)
      }
      if (po.postconditionRefs != null && po.postconditionRefs.nonEmpty) {
        props("postconditionRefs") = po.postconditionRefs.map(r => s"${r.ruleId}|${r.errCode}").mkString(";;")
        props("postRefsCount") = String.valueOf(po.postconditionRefs.size)
      }
    }
    // 服务图完整性批（2026-09-29·形态B 用户拍板）：字段=图节点——每 FieldSpec 一个 Field
    //   节点（conceptId=kn:<noteId>·noteId 即服务端号＝回锚键·带 tenantId 戳过 strict 门）＋
    //   HAS_FIELD 边（宿主概念→字段）＋Field.anchors 属性位（回锚属性·量产批随锚写）。
    //   全走 GraphMutationExecutor（B6 正规腿·用户令：禁 JS 直连图）。
    //   mergeEdge 前置校验要求两端已在：宿主 Concept 本事件已 UpdateNodeProps 存在；
    //   Field 先 Upsert 后连边（时序自洽·Strict 悬空停车场兜底）。
    if (po.fields != null && po.fields.nonEmpty) {
      var fieldCount = 0
      po.fields.foreach { f =>
        if (f.noteId != null && f.noteId.nonEmpty) {
          GraphMutationExecutor.apply(GraphMutationExecutor.UpsertNode("Field", "conceptId",
            s"kn:${f.noteId}",
            Map("name" -> Option(f.name).getOrElse(""), "dataType" -> Option(f.dataType).getOrElse(""),
                "description" -> Option(f.description).getOrElse(""), "role" -> Option(f.role).getOrElse(""),
                "noteId" -> f.noteId, "host" -> po.conceptId,
                "writtenBy" -> (if (f.writtenBy == null) "" else f.writtenBy.mkString(";")),
                "tenantId" -> po.tenantId)), GraphMutationExecutor.ExecutionMode.Strict)
          GraphMutationExecutor.apply(GraphMutationExecutor.MergeEdge("HAS_FIELD",
            "Concept", "conceptId", s"kn:${po.conceptId}",
            "Field", "conceptId", s"kn:${f.noteId}",
            Map("tenantId" -> po.tenantId)), GraphMutationExecutor.ExecutionMode.Strict)
          fieldCount += 1
        }
      }
      props("fieldsCount") = String.valueOf(fieldCount)
    }
    // 19 不载批·第四批（2026-09-30·影响边三连）：影响边三族——端点先在（判例#9·宿主概念/
    //   Field 节点须已落图，Strict 悬空停车场兜底）·边带 tenantId 戳（HAS_FIELD 同款）。
    //   EMITS＝命令概念→事件概念（rel.cem·CEM 因果·形态a 用户拍板）；
    //   WRITES＝事件概念→状态 Field 节点（bh.fold·slot/expr 真源原文随边属性）；
    //   EMITS_PAYLOAD＝事件概念→payload Field 节点（bh.emission·expr=值从哪来）。
    //   三族全空（旧 journal 事件回放/单腿推送）不写——保持节点干净（anchors 空分支同款纪律）。
    if (po.emits != null && po.emits.nonEmpty) {
      var emitsCount = 0
      po.emits.foreach { t =>
        if (t.conceptId != null && t.conceptId.nonEmpty) {
          GraphMutationExecutor.apply(GraphMutationExecutor.MergeEdge("EMITS",
            "Concept", "conceptId", s"kn:${po.conceptId}",
            "Concept", "conceptId", s"kn:${t.conceptId}",
            Map("tenantId" -> po.tenantId)), GraphMutationExecutor.ExecutionMode.Strict)
          emitsCount += 1
        }
      }
      props("emitsCount") = String.valueOf(emitsCount)
    }
    if (po.folds != null && po.folds.nonEmpty) {
      var foldsCount = 0
      po.folds.foreach { f =>
        if (f.fieldNoteId != null && f.fieldNoteId.nonEmpty) {
          GraphMutationExecutor.apply(GraphMutationExecutor.MergeEdge("WRITES",
            "Concept", "conceptId", s"kn:${po.conceptId}",
            "Field", "conceptId", s"kn:${f.fieldNoteId}",
            Map("tenantId" -> po.tenantId, "slot" -> Option(f.slot).getOrElse(""), "expr" -> Option(f.expr).getOrElse(""))),
            GraphMutationExecutor.ExecutionMode.Strict)
          foldsCount += 1
        }
      }
      props("foldsCount") = String.valueOf(foldsCount)
    }
    if (po.emissions != null && po.emissions.nonEmpty) {
      var emissionsCount = 0
      po.emissions.foreach { e =>
        if (e.fieldNoteId != null && e.fieldNoteId.nonEmpty) {
          GraphMutationExecutor.apply(GraphMutationExecutor.MergeEdge("EMITS_PAYLOAD",
            "Concept", "conceptId", s"kn:${po.conceptId}",
            "Field", "conceptId", s"kn:${e.fieldNoteId}",
            Map("tenantId" -> po.tenantId, "slot" -> Option(e.slot).getOrElse(""), "expr" -> Option(e.expr).getOrElse(""))),
            GraphMutationExecutor.ExecutionMode.Strict)
          emissionsCount += 1
        }
      }
      props("emissionsCount") = String.valueOf(emissionsCount)
    }
    // 19 不载批·第五批（2026-09-30）：用例面——steps/extensions 打包属性（uc.step/uc.exceptionFlow
    //   同单位直判·stepsCount/extensionsCount 旁挂）＋UC_WRITES/UC_PUBLISHES 两族边
    //   （用例步骤 writes[].command→命令概念·publishes[]→事件概念·端点先在判例#9）。
    if (po.steps != null && po.steps.nonEmpty) {
      props("steps") = po.steps.map(s => s"${s.no}|${s.text}").mkString(";;")
      props("stepsCount") = String.valueOf(po.steps.size)
    }
    if (po.extensions != null && po.extensions.nonEmpty) {
      props("extensions") = po.extensions.map(s => s"${s.atStep}|${s.text}").mkString(";;")
      props("extensionsCount") = String.valueOf(po.extensions.size)
    }
    if (po.ucWrites != null && po.ucWrites.nonEmpty) {
      var ucw = 0
      po.ucWrites.foreach { t =>
        if (t.conceptId != null && t.conceptId.nonEmpty) {
          GraphMutationExecutor.apply(GraphMutationExecutor.MergeEdge("UC_WRITES",
            "Concept", "conceptId", s"kn:${po.conceptId}",
            "Concept", "conceptId", s"kn:${t.conceptId}",
            Map("tenantId" -> po.tenantId)), GraphMutationExecutor.ExecutionMode.Strict)
          ucw += 1
        }
      }
      props("ucWritesCount") = String.valueOf(ucw)
    }
    if (po.ucPublishes != null && po.ucPublishes.nonEmpty) {
      var ucp = 0
      po.ucPublishes.foreach { t =>
        if (t.conceptId != null && t.conceptId.nonEmpty) {
          GraphMutationExecutor.apply(GraphMutationExecutor.MergeEdge("UC_PUBLISHES",
            "Concept", "conceptId", s"kn:${po.conceptId}",
