NoteGraphViewOnNoteCapturedHandler.scala:
// MANUAL（S2-65 批E）：便签节点＋LINKS 边解析（词表外语义边——from=externalId·端点=Note{name=linkName}
// 自然键·非前置单冒号形态如实丢弃·Strict 悬空停车场＝目标未到阻塞重试后自动续走·
// 退役手写件 DomainEventGraphMappings.note L132-162 语义逐条对齐）
event match {
  case NoteEventPO.Event.NoteCaptured(po) =>
    // S2-72 窗口 FIELD 协议扩展（2026-09-08 用户拍板·通用 JSON 通道）：info 结构化富化并入节点属性
    // （FIELD 便签 info.parent/dataType/source/isKey/origin/writtenBy 等·键前缀 "info."）。
    // 存量 journal 事件系历史代 ScalaPB case class 的 Java 序列化流——缺 info 字段反序列化得 null
    // （S2-72 B2 null 盲区教训），按空串容错；非法 JSON 如实丢弃（不阻塞投影流）。
    val rawInfo = if (po.info == null) "" else po.info
    val infoProps: Map[String, String] = if (rawInfo.trim.nonEmpty) {
      try {
        play.api.libs.json.Json.parse(rawInfo).asOpt[play.api.libs.json.JsObject].map { obj =>
          obj.fields.collect {
            case (k, play.api.libs.json.JsString(s)) => "info." + k -> s
            case (k, play.api.libs.json.JsBoolean(b)) => "info." + k -> b.toString
            case (k, play.api.libs.json.JsNumber(n)) => "info." + k -> n.toString
            case (k, play.api.libs.json.JsArray(arr)) =>
              "info." + k -> arr.map { case play.api.libs.json.JsString(s) => s case other => other.toString }.mkString(",")
            case (k, other) => "info." + k -> other.toString
          }.toMap
        }.getOrElse(Map.empty[String, String])
      } catch { case _: Exception => Map.empty[String, String] }
    } else Map.empty[String, String]
    noteGraphViewRepository.upsertNode(po.noteId, Map(
      "type" -> po.`type`, "name" -> po.name, "content" -> po.content, "sessionId" -> po.sessionId,
      "boardId" -> po.boardId, "externalId" -> po.externalId,
      "timeline" -> po.timeline.toString, "pivotal" -> po.pivotal.toString,
      "tenantId" -> po.tenantId) ++ infoProps)
    // links 空安全：proto 字段进 journal 前的旧 NoteCaptured 反序列化得 null links → NPE 崩溃循环
    // （graph_event_projector-note 卡死 2026-09-06 23:19:08 实录）——按缺省 Nil 处理，旧便签本就无血缘可进图
    val linkSeq = if (po.links == null) Seq.empty[String] else po.links
    val ex = net.imadz.metarch.infrastructure.graph.GraphMutationExecutor
    // S2-82-B4a（2026-09-11）：links verbatim 拍板语义落地——灌入序＝SESSION_ORDER 规范序直排，
    // 前向引用（event→后段 aggregate 等·双向环无拓扑序）由图投影「如实弃置」（full-load.mjs
    // linksOf 注释在案）：DanglingEndpointException 捕获后丢弃本边，不阻塞投影流。
    // 原 Strict 停车场语义假设目标由他流写入，但 Note 节点全由本流同一 envelope 序写入——
    // 等待即死锁（B4a 全量重灌实证：第一张 eventStorming 便签卡死全图投影）。
    // links 数据面（journal＋capturenotedecisionview.links 列）不受影响——图仅为派生读面。
    def mergeEdgeTolerant(m: ex.MergeEdge): Unit = try {
      ex.apply(m, ex.ExecutionMode.Strict)
    } catch { case _: ex.DanglingEndpointException => () } // 如实弃置（按名解析失败容忍·拍板在案）
    linkSeq.iterator.map(_.trim).filter(_.nonEmpty).foreach { raw =>
      val idx = raw.indexOf(':')
      if (idx > 0 && idx < raw.length - 1) { // 非前置单冒号形态——如实丢弃（灌入侧报告对账）
        val linkName = raw.substring(idx + 1).trim
        if (linkName.nonEmpty) {
          mergeEdgeTolerant(ex.MergeEdge("LINKS", "Note", "externalId", po.externalId, "Note", "name", linkName,
              Map("linkType" -> raw.substring(0, idx), "linkTarget" -> raw, "tenantId" -> po.tenantId)))
        }
      }
    }
    // info.parent → LINKS 边（field 便签 → 宿主 readModel 便签·Note{name} 自然键与 links 通道同型·
    // 36 宿主全可解析实证——同上 tolerable：宿主后到则弃置，数据面不受影响）
    infoProps.get("info.parent").filter(_.nonEmpty).foreach { parentName =>
      mergeEdgeTolerant(ex.MergeEdge("LINKS", "Note", "externalId", po.externalId, "Note", "name", parentName,
          Map("linkType" -> "parent", "linkTarget" -> s"parent:$parentName", "tenantId" -> po.tenantId)))
    }
  case _ => () // 非本投影关注事件
}

