        )).copy(tenantId = po.tenantId, definitionId = net.imadz.common.Id.of(po.definitionId), viewName = po.viewName, parentAggregate = po.parentAggregate, description = po.description, fields = po.fields.toList.map(v => net.imadz.metarch.infrastructure.persistence.converters.ReadModelDefinitionProtoConverters.ReadModelFieldSpecConv.fromProto(v)), decisionCommands = po.decisionCommands.toList, viewId = po.viewId, sourceAggregates = po.sourceAggregates.toList, consumesEvents = po.consumesEvents.toList, linkedStories = po.linkedStories.toList, declaredAt = Some(java.time.Instant.ofEpochMilli(po.declaredAt)), declaredBy = po.declaredBy, removedAt = None) // S2-82-B4a：viewId/sourceAggregates/consumesEvents/linkedStories 扩列接线；S2-82-B3：复活清墓碑戳（declare＝重声明·FMD E5-WP1 B2 同款）
    readModelDefinitionDecisionViewRepository.upsert(view)
