        // S2-82-B3 typed 折叠（手写·③层 projectionRefCodes 意图直译：typed List 列折叠＋Conv PO→VO；
        //  发射器 keyPairs 契约外事件——regen-safe：发射器对本类 refCode 跳过不回桩）
        // 甲2（2026-09-25·用户令「都用显式类型」）：载荷由 7 个平行标量改为显式类型 PatchReadModelFieldSpec
        //  （`po.fieldSpec`）——折叠随之改按成员逐位补丁：Option 有值才动 / List 空表不动
        //  （与 domain 侧 EventHandler 的 memberPatch 同义·两处口径必须一致）。
        event match {
          case ReadModelDefinitionEventPO.Event.ReadModelFieldPatched(po) =>
            // proto3 optional message ⇒ Option[PatchReadModelFieldSpecPO]；载荷缺 fieldSpec 即「无可补丁」⇒ 不动。
            po.fieldSpec match {
              case Some(spec) =>
                val existing = scala.concurrent.Await.result(readModelDefinitionDecisionViewRepository.findByIdentity(po.definitionId), scala.concurrent.duration.Duration("10s"))
                val view = existing.getOrElse(net.imadz.metarch.application.projection.repository.ReadModelDefinitionDecisionViewTable.ReadModelDefinitionDecisionView(
                  consumesEvents = Nil, decisionCommands = Nil, declaredAt = None, declaredBy = "",
                  definitionId = net.imadz.common.Id.of(po.definitionId), description = "", fields = Nil,
                  linkedStories = Nil, parentAggregate = "", removedAt = None, sourceAggregates = Nil, // S2-82-B3：removedAt 扩列出生零值
                  tenantId = po.tenantId, viewId = "", viewName = ""))
readModelDefinitionDecisionViewRepository.upsert(view.copy(
                  fields = view.fields.map(f => if (f.fieldName == spec.fieldName) f.copy(
                    dataType = spec.dataType.getOrElse(f.dataType),
                    source = spec.source.getOrElse(f.source),
                    isKey = spec.isKey.getOrElse(f.isKey),
                    origin = spec.origin.getOrElse(f.origin),
                    uiLabel = spec.uiLabel.getOrElse(f.uiLabel),
                    writtenBy = (if (spec.writtenBy.isEmpty) f.writtenBy else spec.writtenBy.toList)) else f)))
              case None => ()
            }
          case _ => () // 非本投影关注事件（组合分发器会送全族 envelope）
        }

