//   rebuilder（ReadmodelsRebuild）滤 removedAt 非空行。FMD OnFieldModelRemoved 同款先例。
//   幂等：已戳行跳过（重复 Remove 不重刷时间戳）；查无行静默跳过。
event match {
  case ReadModelDefinitionEventPO.Event.ReadModelRemoved(po) =>
    val existing = scala.concurrent.Await.result(
      readModelDefinitionDecisionViewRepository.findByIdentity(po.definitionId),
      scala.concurrent.duration.Duration("10s"))
    existing.foreach { row =>
      if (row.removedAt.isEmpty) { // 幂等守卫（Option[Instant]·None==null 恒 false 惯用法退役）
        readModelDefinitionDecisionViewRepository.upsert(row.copy(
          removedAt = Some(if (po.timestamp > 0) java.time.Instant.ofEpochMilli(po.timestamp) else java.time.Instant.now())
        ))
      }
    }
  case _ => ()
}

