UserLookupByEmailOrPhoneViewOnUserProfil:
// strOr：旧事件载荷 null 容错（S2-73 零哨兵·converter 判例同律）
def strOr(s: String): String = if (s == null) "" else s
// 挂账全清批 B4（2026-10-05）：??? 桩根修——re-key（键变时旧键行置 REKEYED 哨兵〔repo 无 delete·软语义〕＋新键 upsert；键未变就近刷新）。
event match {
  case UserEventPO.Event.UserProfileUpdated(po) =>
    val rows = scala.concurrent.Await.result(userLookupByEmailOrPhoneViewRepository.findByUserId(po.userId), scala.concurrent.duration.Duration("10s"))
    val newEmail = strOr(po.email); val newPhone = strOr(po.phoneNumber)
    rows.foreach { row =>
      val keyChanged = row.email != newEmail || row.phoneNumber != newPhone
      if (keyChanged) {
        // 旧键行置哨兵（查询侧按 status 过滤·软语义替代 delete——repo 无 delete 的降级裁决）
        userLookupByEmailOrPhoneViewRepository.upsert(row.copy(status = "REKEYED"))
        val fresh = net.imadz.metarch.application.projection.repository.UserLookupByEmailOrPhoneViewTable.UserLookupByEmailOrPhoneView(displayName = strOr(po.displayName), email = newEmail, phoneNumber = newPhone, status = row.status, userId = net.imadz.common.Id.of(po.userId))
        userLookupByEmailOrPhoneViewRepository.upsert(fresh)
      } else {
        userLookupByEmailOrPhoneViewRepository.upsert(row.copy(displayName = strOr(po.displayName)))
      }
    }
    if (rows.isEmpty) {
      // 反查空（未 Registered 先 ProfileUpdated·旧事件流乱序容忍）：直接以新键建行
      val fresh = net.imadz.metarch.application.projection.repository.UserLookupByEmailOrPhoneViewTable.UserLookupByEmailOrPhoneView(displayName = strOr(po.displayName), email = newEmail, phoneNumber = newPhone, status = "ACTIVE", userId = net.imadz.common.Id.of(po.userId))
      userLookupByEmailOrPhoneViewRepository.upsert(fresh)
    }
  case _ => () // 非本投影关注事件
}

